"use strict";
/* Pink PDF Plus — shared client logic. Each tool page is static HTML generated by build.js;
   this file wires up the upload box and runs the tool selected by <div id="tool" data-tool="...">. */

const $ = (s, r = document) => r.querySelector(s);
const A4 = [595.28, 841.89];
const LETTER = [612, 792];
const fmtBytes = b => b < 1024 ? b + " B" : b < 1048576 ? (b / 1024).toFixed(1) + " KB" : (b / 1048576).toFixed(2) + " MB";

let toastTimer;
function toast(msg) {
  const t = $("#toast"); if (!t) return;
  t.textContent = msg; t.classList.add("show");
  clearTimeout(toastTimer); toastTimer = setTimeout(() => t.classList.remove("show"), 2600);
}

/* ---------- helpers ---------- */
async function fileToImage(file) {
  try { return await createImageBitmap(file); }
  catch (e) { throw new Error(file.name + ": this image can't be opened by your browser (try JPG, PNG or WebP). iPhone HEIC photos: use the HEIC to JPG tool."); }
}
function bmpToCanvas(bmp, maxW) {
  let w = bmp.width, h = bmp.height;
  if (maxW && w > maxW) { h = Math.round(h * maxW / w); w = maxW; }
  const c = document.createElement("canvas"); c.width = w; c.height = h;
  c.getContext("2d").drawImage(bmp, 0, 0, w, h);
  return c;
}
function canvasToBlob(canvas, type, quality) {
  return new Promise((res, rej) => canvas.toBlob(b => b ? res(b) : rej(new Error("Could not encode the image.")), type, quality));
}
const baseName = n => n.replace(/\.[^.]+$/, "");
function uniqueName(used, name) {
  if (!used.has(name)) { used.add(name); return name; }
  const m = name.match(/^(.*?)(\.[^.]*)?$/); let i = 2, cand;
  do { cand = m[1] + "-" + i + (m[2] || ""); i++; } while (used.has(cand));
  used.add(cand); return cand;
}
/* "1-3, 5, 8-10" -> [0,1,2,4,7,8,9] (0-based, in listed order, no duplicates) */
function parseRanges(str, max) {
  const out = [], seen = new Set();
  for (const part of str.split(",").map(s => s.trim()).filter(Boolean)) {
    const m = part.match(/^(\d+)(?:\s*-\s*(\d+))?$/);
    if (!m) throw new Error("I couldn't understand \"" + part + "\". Use numbers like 1-3, 5, 8-10.");
    let a = parseInt(m[1], 10), b = m[2] ? parseInt(m[2], 10) : a;
    if (a > b) [a, b] = [b, a];
    if (a < 1 || b > max) throw new Error("Page " + (a < 1 ? a : b) + " is outside this PDF (it has " + max + " page" + (max > 1 ? "s" : "") + ").");
    for (let p = a; p <= b; p++) if (!seen.has(p)) { seen.add(p); out.push(p - 1); }
  }
  return out;
}
async function loadPdf(file) {
  try { return await PDFLib.PDFDocument.load(await file.arrayBuffer(), { ignoreEncryption: true }); }
  catch (e) { throw new Error(file.name + " couldn't be read. It may be damaged or password-protected."); }
}

/* ---------- image converters (PNG/WebP -> JPG, JPG -> PNG) ---------- */
function imageConverter(mime, ext, zipName) {
  return async (files, ui) => {
    const q = (parseInt(ui.val("opt-q")) || 92) / 100;
    const bg = ui.val("opt-bg") || "#ffffff";
    const zip = new JSZip(), used = new Set();
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 92, "Converting " + files[i].name + "…");
      const bmp = await fileToImage(files[i]);
      const c = document.createElement("canvas"); c.width = bmp.width; c.height = bmp.height;
      const ctx = c.getContext("2d");
      if (mime === "image/jpeg") { ctx.fillStyle = bg; ctx.fillRect(0, 0, c.width, c.height); }
      ctx.drawImage(bmp, 0, 0);
      bmp.close && bmp.close();
      const blob = await canvasToBlob(c, mime, mime === "image/png" ? undefined : q);
      const name = baseName(files[i].name) + "." + ext;
      if (files.length === 1) { ui.done(blob, name, "Converted to " + ext.toUpperCase() + " 🎉"); return; }
      zip.file(uniqueName(used, name), blob);
    }
    ui.pg(96, "Packing ZIP…");
    ui.done(await zip.generateAsync({ type: "blob" }), zipName, files.length + " images converted 🎉");
  };
}

/* ---------- compress to a target size ---------- */
async function jpegUnder(bmp, targetBytes) {
  let scale = 1, best = null;
  for (let attempt = 0; attempt < 10; attempt++) {
    const w = Math.max(1, Math.round(bmp.width * scale)), h = Math.max(1, Math.round(bmp.height * scale));
    if (w < 40 || h < 40) break;
    const c = document.createElement("canvas"); c.width = w; c.height = h;
    const ctx = c.getContext("2d"); ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, w, h); ctx.drawImage(bmp, 0, 0, w, h);
    const hiBlob = await canvasToBlob(c, "image/jpeg", 0.92);
    if (hiBlob.size <= targetBytes) return { blob: hiBlob, w, h };
    const QMIN = 0.35;
    const loBlob = await canvasToBlob(c, "image/jpeg", QMIN);
    if (!best || loBlob.size < best.blob.size) best = { blob: loBlob, w, h };
    if (loBlob.size > targetBytes) { scale *= Math.max(0.4, Math.min(0.92, Math.sqrt(targetBytes / loBlob.size) * 0.96)); continue; }
    let lo = QMIN, hi = 0.92, found = { blob: loBlob, w, h };
    for (let k = 0; k < 7; k++) {
      const mid = (lo + hi) / 2, b = await canvasToBlob(c, "image/jpeg", mid);
      if (b.size <= targetBytes) { found = { blob: b, w, h }; lo = mid; } else hi = mid;
    }
    return found;
  }
  return best && best.blob.size <= targetBytes ? best : null;
}

/* ================= Tool runners ================= */
const RUNNERS = {
  "jpg-to-pdf": async (files, ui) => {
    const size = ui.val("opt-size");
    const { PDFDocument } = PDFLib;
    const pdf = await PDFDocument.create();
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 90, "Adding " + files[i].name + "…");
      const bytes = await files[i].arrayBuffer();
      let img;
      try { img = await pdf.embedJpg(bytes); } catch (e) { try { img = await pdf.embedPng(bytes); } catch (e2) { throw new Error(files[i].name + " isn't a JPG/PNG file."); } }
      let pw, ph;
      if (size === "a4") { [pw, ph] = A4; } else if (size === "letter") { [pw, ph] = LETTER; } else { pw = img.width; ph = img.height; }
      const page = pdf.addPage([pw, ph]);
      const s = Math.min(pw / img.width, ph / img.height);
      const w = img.width * s, h = img.height * s;
      page.drawImage(img, { x: (pw - w) / 2, y: (ph - h) / 2, width: w, height: h });
    }
    ui.pg(95, "Saving PDF…");
    const out = await pdf.save();
    ui.done(new Blob([out], { type: "application/pdf" }), "pink-pdf-plus-jpg-to-pdf.pdf", "PDF created from " + files.length + " image" + (files.length > 1 ? "s" : "") + " 🎉");
  },

  "pdf-to-jpg": async (files, ui) => {
    const scale = parseFloat(ui.val("opt-q"));
    const buf = await files[0].arrayBuffer();
    const doc = await pdfjsLib.getDocument({ data: buf }).promise;
    const zip = new JSZip();
    for (let p = 1; p <= doc.numPages; p++) {
      ui.pg(((p - 1) / doc.numPages) * 92, "Rendering page " + p + " of " + doc.numPages + "…");
      const page = await doc.getPage(p);
      const vp = page.getViewport({ scale });
      const c = document.createElement("canvas");
      c.width = Math.ceil(vp.width); c.height = Math.ceil(vp.height);
      await page.render({ canvasContext: c.getContext("2d"), viewport: vp }).promise;
      const blob = await canvasToBlob(c, "image/jpeg", 0.92);
      if (doc.numPages === 1) { ui.done(blob, baseName(files[0].name) + ".jpg", "1 page exported as JPG 🎉"); return; }
      zip.file("page-" + String(p).padStart(2, "0") + ".jpg", blob);
    }
    ui.pg(96, "Packing ZIP…");
    ui.done(await zip.generateAsync({ type: "blob" }), baseName(files[0].name) + "-pages.zip", doc.numPages + " pages exported as JPG (ZIP) 🎉");
  },

  "merge-pdf": async (files, ui) => {
    if (files.length < 2) throw new Error("Please add at least 2 PDF files to merge.");
    const { PDFDocument } = PDFLib;
    const merged = await PDFDocument.create();
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 92, "Merging " + files[i].name + "…");
      const src = await loadPdf(files[i]);
      const pages = await merged.copyPages(src, src.getPageIndices());
      pages.forEach(p => merged.addPage(p));
    }
    ui.pg(96, "Saving merged PDF…");
    const out = await merged.save();
    ui.done(new Blob([out], { type: "application/pdf" }), "pink-pdf-plus-merged.pdf", files.length + " PDFs merged into one 🎉");
  },

  "compress-image": async (files, ui) => {
    const q = parseInt(ui.val("opt-q")) / 100;
    const maxW = parseInt(ui.val("opt-w")) || 0;
    const zip = new JSZip(), used = new Set(); let n = 0;
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 92, "Compressing " + files[i].name + "…");
      const bmp = await fileToImage(files[i]);
      const c = bmpToCanvas(bmp, maxW || (bmp.width > 2600 ? 2600 : 0));
      const isPng = /png$/i.test(files[i].name);
      const type = isPng ? "image/png" : "image/webp";
      const blob = await canvasToBlob(c, type, q);
      bmp.close && bmp.close();
      const ext = isPng ? "png" : "webp";
      if (files.length === 1) {
        const pct = files[i].size ? Math.round((1 - blob.size / files[i].size) * 100) : 0;
        ui.done(blob, baseName(files[i].name) + "-compressed." + ext,
          "Compressed " + fmtBytes(files[i].size) + " → " + fmtBytes(blob.size) + " (" + (pct > 0 ? pct + "% smaller" : Math.abs(pct) + "% larger") + ") 🎉");
        return;
      }
      zip.file(uniqueName(used, baseName(files[i].name) + "-compressed." + ext), blob); n++;
    }
    ui.pg(96, "Packing ZIP…");
    ui.done(await zip.generateAsync({ type: "blob" }), "pink-pdf-plus-compressed.zip", n + " images compressed 🎉");
  },

  "resize-image": async (files, ui) => {
    const wIn = parseInt(ui.val("opt-w")), hIn = parseInt(ui.val("opt-h"));
    if (!wIn && !hIn) throw new Error("Enter a width or a height to resize to.");
    const zip = new JSZip(), used = new Set();
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 92, "Resizing " + files[i].name + "…");
      const bmp = await fileToImage(files[i]);
      const w = wIn || Math.round(bmp.width * (hIn / bmp.height));
      const h = hIn || Math.round(bmp.height * (wIn / bmp.width));
      const c = document.createElement("canvas"); c.width = w; c.height = h;
      const fmt = ui.val("opt-f") === "original"
        ? (/png$/i.test(files[i].name) ? "image/png" : /webp$/i.test(files[i].name) ? "image/webp" : "image/jpeg")
        : ui.val("opt-f");
      const ctx = c.getContext("2d");
      if (fmt === "image/jpeg") { ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, w, h); }
      ctx.drawImage(bmp, 0, 0, w, h);
      bmp.close && bmp.close();
      const blob = await canvasToBlob(c, fmt, 0.92);
      const ext = { "image/png": "png", "image/webp": "webp", "image/jpeg": "jpg" }[fmt];
      const name = baseName(files[i].name) + "-" + w + "x" + h + "." + ext;
      if (files.length === 1) { ui.done(blob, name, "Resized to " + w + "×" + h + " px 🎉"); return; }
      zip.file(uniqueName(used, name), blob);
    }
    ui.pg(96, "Packing ZIP…");
    ui.done(await zip.generateAsync({ type: "blob" }), "pink-pdf-plus-resized.zip", files.length + " images resized 🎉");
  },

  "image-to-pdf": async (files, ui) => {
    const margin = ui.val("opt-l") === "margin" ? 40 : 0;
    const { PDFDocument } = PDFLib;
    const pdf = await PDFDocument.create();
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 92, "Placing " + files[i].name + "…");
      const bytes = await files[i].arrayBuffer();
      let img;
      try { img = await pdf.embedJpg(bytes); } catch (e) { try { img = await pdf.embedPng(bytes); } catch (e2) { throw new Error(files[i].name + ": only JPG and PNG can be embedded in a PDF."); } }
      const [pw, ph] = A4;
      const page = pdf.addPage([pw, ph]);
      const s = Math.min((pw - 2 * margin) / img.width, (ph - 2 * margin) / img.height);
      const w = img.width * s, h = img.height * s;
      page.drawImage(img, { x: (pw - w) / 2, y: (ph - h) / 2, width: w, height: h });
    }
    ui.pg(96, "Saving PDF…");
    const out = await pdf.save();
    ui.done(new Blob([out], { type: "application/pdf" }), "pink-pdf-plus-images.pdf", files.length + " image" + (files.length > 1 ? "s" : "") + " placed on A4 pages 🎉");
  },

  "a4-pdf-creator": async (files, ui) => {
    const text = ui.val("opt-text").trim();
    if (!text) throw new Error("Please type some text first.");
    const fs = Math.min(48, Math.max(8, parseInt(ui.val("opt-fs")) || 12));
    const m = parseInt(ui.val("opt-m"));
    const { PDFDocument, StandardFonts, rgb } = PDFLib;
    const pdf = await PDFDocument.create();
    const font = await pdf.embedFont(StandardFonts.Helvetica);
    const [pw, ph] = A4;
    const lineH = fs * 1.45, maxW = pw - 2 * m;
    const lines = [];
    const fits = t => { try { return font.widthOfTextAtSize(t, fs) <= maxW; } catch (e) { throw new Error("This tool supports Latin characters only (A–Z, numbers, common symbols)."); } };
    for (const para of text.split(/\r?\n/)) {
      if (!para.trim()) { lines.push(""); continue; }
      let line = "";
      for (const w of para.split(/\s+/).filter(Boolean)) {
        const t = line ? line + " " + w : w;
        if (fits(t)) line = t;
        else {
          if (line) lines.push(line);
          line = w;
          if (!fits(w)) { let chunk = ""; for (const ch of w) { if (fits(chunk + ch)) chunk += ch; else { lines.push(chunk); chunk = ch; } } line = chunk; }
        }
      }
      if (line) lines.push(line);
    }
    const perPage = Math.floor((ph - 2 * m) / lineH);
    if (!perPage) throw new Error("Font size is too large for the page. Try a smaller size.");
    for (let i = 0; i < lines.length; i += perPage) {
      ui.pg(60, "Writing page " + (i / perPage + 1) + "…");
      const page = pdf.addPage([pw, ph]);
      lines.slice(i, i + perPage).forEach((l, j) => { if (l) page.drawText(l, { x: m, y: ph - m - fs - j * lineH, size: fs, font, color: rgb(0.15, 0.08, 0.12) }); });
    }
    ui.pg(92, "Saving PDF…");
    const out = await pdf.save();
    const pages = Math.ceil(lines.length / perPage);
    ui.done(new Blob([out], { type: "application/pdf" }), "pink-pdf-plus-a4-document.pdf", "A4 PDF created (" + pages + " page" + (pages > 1 ? "s" : "") + ") 🎉");
  },

  "image-format-converter": async (files, ui) => {
    const fmt = ui.val("opt-f");
    const ext = { "image/png": "png", "image/webp": "webp", "image/jpeg": "jpg" }[fmt];
    const zip = new JSZip(), used = new Set();
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 92, "Converting " + files[i].name + "…");
      const bmp = await fileToImage(files[i]);
      const c = document.createElement("canvas"); c.width = bmp.width; c.height = bmp.height;
      const ctx = c.getContext("2d");
      if (fmt === "image/jpeg") { ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, c.width, c.height); }
      ctx.drawImage(bmp, 0, 0);
      bmp.close && bmp.close();
      const blob = await canvasToBlob(c, fmt, fmt === "image/png" ? undefined : 0.92);
      if (files.length === 1) { ui.done(blob, baseName(files[i].name) + "." + ext, "Converted to " + ext.toUpperCase() + " 🎉"); return; }
      zip.file(uniqueName(used, baseName(files[i].name) + "." + ext), blob);
    }
    ui.pg(96, "Packing ZIP…");
    ui.done(await zip.generateAsync({ type: "blob" }), "pink-pdf-plus-converted.zip", files.length + " images converted 🎉");
  },

  /* ---------- new tools ---------- */
  "png-to-jpg": imageConverter("image/jpeg", "jpg", "pink-pdf-plus-png-to-jpg.zip"),
  "webp-to-jpg": imageConverter("image/jpeg", "jpg", "pink-pdf-plus-webp-to-jpg.zip"),
  "jpg-to-png": imageConverter("image/png", "png", "pink-pdf-plus-jpg-to-png.zip"),

  "heic-to-jpg": async (files, ui) => {
    if (typeof heic2any === "undefined") throw new Error("The HEIC converter couldn't be loaded. Check your internet connection and reload the page.");
    const q = (parseInt(ui.val("opt-q")) || 90) / 100;
    const zip = new JSZip(), used = new Set(); const outs = [];
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 92, "Converting " + files[i].name + "…");
      let blobs;
      try {
        const r = await heic2any({ blob: files[i], toType: "image/jpeg", quality: q });
        blobs = Array.isArray(r) ? r : [r];
      } catch (e) {
        try { /* some browsers (Safari) can decode HEIC natively */
          const bmp = await createImageBitmap(files[i]);
          const c = document.createElement("canvas"); c.width = bmp.width; c.height = bmp.height;
          c.getContext("2d").drawImage(bmp, 0, 0); bmp.close && bmp.close();
          blobs = [await canvasToBlob(c, "image/jpeg", q)];
        } catch (e2) { throw new Error(files[i].name + " couldn't be converted. Make sure it is a valid HEIC/HEIF photo."); }
      }
      blobs.forEach((b, k) => outs.push({ blob: b, name: baseName(files[i].name) + (blobs.length > 1 ? "-" + (k + 1) : "") + ".jpg" }));
    }
    if (outs.length === 1) { ui.done(outs[0].blob, outs[0].name, "Converted to JPG 🎉"); return; }
    outs.forEach(o => zip.file(uniqueName(used, o.name), o.blob));
    ui.pg(96, "Packing ZIP…");
    ui.done(await zip.generateAsync({ type: "blob" }), "pink-pdf-plus-heic-to-jpg.zip", outs.length + " photos converted 🎉");
  },

  "compress-image-to-100kb": async (files, ui) => {
    const kb = parseInt(ui.val("opt-t")) || 100, target = kb * 1024;
    const zip = new JSZip(), used = new Set(); const notes = [];
    for (let i = 0; i < files.length; i++) {
      ui.pg((i / files.length) * 92, "Compressing " + files[i].name + "…");
      let outBlob, name, msg;
      if (files[i].size <= target) {
        outBlob = files[i]; name = files[i].name;
        msg = files[i].name + " is already " + fmtBytes(files[i].size) + " (under " + kb + " KB) — returned unchanged.";
      } else {
        const bmp = await fileToImage(files[i]);
        const r = await jpegUnder(bmp, target);
        bmp.close && bmp.close();
        if (!r) throw new Error(files[i].name + " couldn't be reduced to " + kb + " KB without making it too small. Try a larger target size.");
        outBlob = r.blob; name = baseName(files[i].name) + "-" + kb + "kb.jpg";
        msg = fmtBytes(files[i].size) + " → " + fmtBytes(r.blob.size) + " (" + r.w + "×" + r.h + " px)";
      }
      if (files.length === 1) { ui.done(outBlob, name, msg + " 🎉"); return; }
      zip.file(uniqueName(used, name), outBlob); notes.push(msg);
    }
    ui.pg(96, "Packing ZIP…");
    ui.done(await zip.generateAsync({ type: "blob" }), "pink-pdf-plus-compressed-" + kb + "kb.zip", files.length + " images compressed to under " + kb + " KB 🎉");
  },

  "split-pdf": async (files, ui) => {
    const mode = ui.val("opt-mode");
    const src = await loadPdf(files[0]);
    const total = src.getPageCount(), base = baseName(files[0].name);
    const { PDFDocument } = PDFLib;
    const pad = n => String(n).padStart(String(total).length, "0");
    if (mode === "range") {
      const idx = parseRanges(ui.val("opt-range"), total);
      if (!idx.length) throw new Error("Enter the pages you want, for example 1-3, 5, 8.");
      ui.pg(40, "Extracting " + idx.length + " page(s)…");
      const out = await PDFDocument.create();
      (await out.copyPages(src, idx)).forEach(p => out.addPage(p));
      ui.done(new Blob([await out.save()], { type: "application/pdf" }), base + "-pages.pdf", idx.length + " page" + (idx.length > 1 ? "s" : "") + " extracted 🎉");
      return;
    }
    let groups = [];
    if (mode === "each") { for (let i = 0; i < total; i++) groups.push([i]); }
    else {
      const n = Math.max(1, parseInt(ui.val("opt-n")) || 1);
      for (let i = 0; i < total; i += n) groups.push(Array.from({ length: Math.min(n, total - i) }, (_, k) => i + k));
    }
    if (groups.length === 1) throw new Error("This PDF would not be split (it has only " + total + " page" + (total > 1 ? "s" : "") + " for that setting). Try a smaller number.");
    const zip = new JSZip();
    for (let g = 0; g < groups.length; g++) {
      ui.pg((g / groups.length) * 92, "Creating part " + (g + 1) + " of " + groups.length + "…");
      const out = await PDFDocument.create();
      (await out.copyPages(src, groups[g])).forEach(p => out.addPage(p));
      const label = groups[g].length === 1 ? "page-" + pad(groups[g][0] + 1) : "pages-" + pad(groups[g][0] + 1) + "-" + pad(groups[g][groups[g].length - 1] + 1);
      zip.file(base + "-" + label + ".pdf", await out.save());
    }
    ui.pg(96, "Packing ZIP…");
    ui.done(await zip.generateAsync({ type: "blob" }), base + "-split.zip", "Split into " + groups.length + " PDFs 🎉");
  },

  "rotate-pdf": async (files, ui) => {
    const angle = parseInt(ui.val("opt-a")) || 90;
    const pdf = await loadPdf(files[0]);
    const pages = pdf.getPages();
    const rangeStr = ui.val("opt-range").trim();
    const idx = rangeStr ? parseRanges(rangeStr, pages.length) : pages.map((_, i) => i);
    const { degrees } = PDFLib;
    idx.forEach((i, k) => {
      ui.pg((k / idx.length) * 90, "Rotating page " + (i + 1) + "…");
      const p = pages[i];
      p.setRotation(degrees((p.getRotation().angle + angle) % 360));
    });
    ui.pg(95, "Saving PDF…");
    ui.done(new Blob([await pdf.save()], { type: "application/pdf" }), baseName(files[0].name) + "-rotated.pdf", idx.length + " page" + (idx.length > 1 ? "s" : "") + " rotated 🎉");
  },

  "pdf-to-text": async (files, ui) => {
    const buf = await files[0].arrayBuffer();
    let doc;
    try { doc = await pdfjsLib.getDocument({ data: buf }).promise; }
    catch (e) { throw new Error("This PDF couldn't be read. It may be damaged or password-protected."); }
    const sep = ui.val("opt-sep") === "yes";
    let all = "";
    for (let p = 1; p <= doc.numPages; p++) {
      ui.pg(((p - 1) / doc.numPages) * 92, "Reading page " + p + " of " + doc.numPages + "…");
      const tc = await (await doc.getPage(p)).getTextContent();
      let out = "", lastY = null;
      for (const it of tc.items) {
        if (typeof it.str !== "string") continue;
        const y = it.transform ? it.transform[5] : null;
        if (lastY !== null && y !== null && Math.abs(y - lastY) > (it.height || 8) * 0.6 && out && !out.endsWith("\n")) out += "\n";
        out += it.str;
        if (it.hasEOL && !out.endsWith("\n")) out += "\n";
        if (y !== null) lastY = y;
      }
      all += out.trim() + (sep && p < doc.numPages ? "\n\n----- Page " + (p + 1) + " -----\n\n" : "\n\n");
    }
    if (!all.replace(/[-\s]|Page \d+/g, "").length) throw new Error("No text found. This PDF looks like a scan or a picture of a document, so there is no text to extract (OCR isn't supported yet).");
    ui.done(new Blob(["﻿" + all.trim() + "\n"], { type: "text/plain;charset=utf-8" }), baseName(files[0].name) + ".txt", "Text extracted from " + doc.numPages + " page" + (doc.numPages > 1 ? "s" : "") + " 🎉");
  }
};

/* ================= Page behaviour ================= */
function accepted(file, accept) {
  if (!accept) return true;
  const name = file.name.toLowerCase(), type = (file.type || "").toLowerCase();
  return accept.toLowerCase().split(",").map(s => s.trim()).filter(Boolean).some(a =>
    a.startsWith(".") ? name.endsWith(a) : a.endsWith("/*") ? type.startsWith(a.slice(0, -1)) : type === a);
}

function initTool(root) {
  const id = root.dataset.tool, accept = root.dataset.accept || "", multiple = root.dataset.multiple === "1";
  const run = RUNNERS[id];
  const dz = $("#dz", root), fi = $("#fi", root), pv = $("#pv", root), cnt = $("#cnt", root),
        pg = $("#pg", root), bar = $("#bar", root), pglbl = $("#pglbl", root),
        runBtn = $("#run", root), err = $("#err", root), res = $("#res", root);
  const state = { files: [] };
  const runLabel = runBtn.innerHTML;

  const qv = $("#qv"), qs = $("#opt-q");
  if (qv && qs) qs.addEventListener("input", () => { qv.textContent = qs.value; });

  const ui = {
    val: oid => { const e = document.getElementById(oid); return e ? e.value : ""; },
    pg: (pct, msg) => { pg.classList.add("show"); bar.style.width = Math.min(100, pct) + "%"; pglbl.textContent = msg || ""; },
    done: (blob, filename, msg) => {
      bar.style.width = "100%"; pglbl.textContent = "";
      const dl = $("#dl", root);
      if (dl.dataset.url) URL.revokeObjectURL(dl.dataset.url);
      const url = URL.createObjectURL(blob); dl.dataset.url = url;
      dl.href = url; dl.download = filename;
      $("#resmsg", root).textContent = msg + " (" + fmtBytes(blob.size) + ")";
      res.classList.add("show");
      dl.onclick = () => toast("Downloading " + filename + "…");
    }
  };
  const showErr = m => { err.textContent = "⚠️ " + m; err.classList.add("show"); };
  const clearErr = () => err.classList.remove("show");

  function renderPreview() {
    if (!pv) return;
    pv.innerHTML = "";
    state.files.forEach((f, i) => {
      const d = document.createElement("div"); d.className = "thumb";
      if (/^image\/(jpeg|png|webp|gif|bmp|avif)$/.test(f.type)) {
        const img = document.createElement("img");
        img.src = URL.createObjectURL(f);
        img.onload = () => URL.revokeObjectURL(img.src);
        d.appendChild(img);
      } else {
        const cv = document.createElement("canvas"); cv.width = cv.height = 172;
        const x = cv.getContext("2d"); x.fillStyle = "#ffe3ee"; x.fillRect(0, 0, 172, 172);
        x.fillStyle = "#d81b60"; x.font = "bold 40px Arial"; x.textAlign = "center";
        const m = f.name.match(/\.([a-z0-9]+)$/i);
        x.fillText((f.type === "application/pdf" ? "PDF" : (m ? m[1] : "FILE")).toUpperCase().slice(0, 5), 86, 100);
        d.appendChild(cv);
      }
      const lbl = document.createElement("div"); lbl.className = "lbl"; lbl.textContent = f.name; d.appendChild(lbl);
      const rm = document.createElement("button"); rm.className = "rm"; rm.textContent = "×"; rm.title = "Remove"; rm.setAttribute("aria-label", "Remove " + f.name);
      rm.onclick = e => { e.stopPropagation(); state.files.splice(i, 1); renderPreview(); };
      d.appendChild(rm); pv.appendChild(d);
    });
    cnt.textContent = state.files.length ? state.files.length + " file(s) • " + fmtBytes(state.files.reduce((a, f) => a + f.size, 0)) : "No files yet";
  }

  function addFiles(list) {
    clearErr(); res.classList.remove("show");
    const arr = [...list];
    const bad = arr.filter(f => !accepted(f, accept));
    if (bad.length) showErr("Skipped unsupported: " + bad.map(b => b.name).join(", ") + ". " + (root.dataset.hint || ""));
    const good = arr.filter(f => !bad.includes(f));
    state.files = multiple ? state.files.concat(good) : good.slice(0, 1);
    renderPreview();
    if (good.length) toast("Added " + good.length + " file(s) ✨");
  }

  if (dz) {
    dz.onclick = () => fi.click();
    dz.onkeydown = e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); fi.click(); } };
    fi.onchange = () => { addFiles(fi.files); fi.value = ""; };
    ["dragenter", "dragover"].forEach(ev => dz.addEventListener(ev, e => { e.preventDefault(); dz.classList.add("over"); }));
    ["dragleave", "drop"].forEach(ev => dz.addEventListener(ev, e => { e.preventDefault(); dz.classList.remove("over"); }));
    dz.addEventListener("drop", e => addFiles(e.dataTransfer.files));
  }

  $("#again", root).onclick = () => {
    state.files = []; renderPreview(); res.classList.remove("show");
    pg.classList.remove("show"); bar.style.width = "0%"; pglbl.textContent = ""; clearErr();
    runBtn.disabled = false;
    const t = document.getElementById("opt-text"); if (t) t.focus();
    toast("Ready to go again 🌸");
  };

  runBtn.onclick = async () => {
    if (accept && !state.files.length) { showErr("Please add at least one file first — tap the box above to browse or drag files in."); return; }
    clearErr(); res.classList.remove("show");
    runBtn.disabled = true; runBtn.textContent = "⏳ Working…";
    try {
      await run(state.files, ui);
      toast("Done! Your download is ready ✨");
    } catch (e) {
      console.error(e);
      showErr(e.message || "Something went wrong while processing. Please try a different file.");
      pg.classList.remove("show");
    } finally {
      runBtn.disabled = false; runBtn.innerHTML = runLabel;
    }
  };
}

/* ---------- boot ---------- */
(function boot() {
  const burger = $("#burger"), menu = $("#mobileMenu");
  if (burger && menu) {
    burger.onclick = () => { const open = menu.classList.toggle("open"); burger.setAttribute("aria-expanded", open); };
    menu.addEventListener("click", e => { if (e.target.tagName === "A") menu.classList.remove("open"); });
  }
  const root = document.getElementById("tool");
  if (root) initTool(root);
  window.__pinkReady = true;
})();
